ALTER TABLE partners ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_partners_workspace_status (workspace_id,status), ADD CONSTRAINT fk_partners_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
