ALTER TABLE revenues ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_revenues_workspace_status (workspace_id,status), ADD CONSTRAINT fk_revenues_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
ALTER TABLE commissions ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_commissions_workspace_status (workspace_id,status), ADD CONSTRAINT fk_commissions_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
ALTER TABLE partner_payouts ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_partner_payouts_workspace_status (workspace_id,status), ADD CONSTRAINT fk_partner_payouts_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
ALTER TABLE partner_disputes ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_partner_disputes_workspace_status (workspace_id,status), ADD CONSTRAINT fk_partner_disputes_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
ALTER TABLE campaign_assets ADD COLUMN workspace_id CHAR(36) NULL AFTER id, ADD KEY idx_campaign_assets_workspace_status (workspace_id,status), ADD CONSTRAINT fk_campaign_assets_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE RESTRICT;
UPDATE partners SET workspace_id='00000000-0000-0000-0000-000000000001' WHERE workspace_id IS NULL;
UPDATE referral_links rl LEFT JOIN partner_campaigns pc ON pc.id=rl.campaign_id SET rl.workspace_id=COALESCE(pc.workspace_id,'00000000-0000-0000-0000-000000000001') WHERE rl.workspace_id IS NULL;
UPDATE revenues r JOIN orders o ON o.id=r.order_id SET r.workspace_id=o.workspace_id WHERE r.workspace_id IS NULL;
UPDATE commissions c LEFT JOIN revenues r ON r.id=c.revenue_id LEFT JOIN orders o ON o.id=c.order_id SET c.workspace_id=COALESCE(r.workspace_id,o.workspace_id,'00000000-0000-0000-0000-000000000001') WHERE c.workspace_id IS NULL;
UPDATE partner_payouts pp JOIN partners p ON p.id=pp.partner_id SET pp.workspace_id=p.workspace_id WHERE pp.workspace_id IS NULL;
UPDATE partner_disputes d LEFT JOIN leads l ON l.id=d.lead_id LEFT JOIN partner_campaigns c ON c.id=d.campaign_id LEFT JOIN commissions cm ON cm.id=d.commission_id LEFT JOIN partners p ON p.id=d.partner_id SET d.workspace_id=COALESCE(l.workspace_id,c.workspace_id,cm.workspace_id,p.workspace_id,'00000000-0000-0000-0000-000000000001') WHERE d.workspace_id IS NULL;
UPDATE campaign_assets a JOIN partner_campaigns c ON c.id=a.campaign_id SET a.workspace_id=c.workspace_id WHERE a.workspace_id IS NULL;
